import backtrader as bt


class BounceSupportUptrend(bt.Strategy):
    params = (
        ('ema_fast_period', 20),
        ('ema_slow_period', 50),
        ('rsi_period', 14),
        ('vol_sma_period', 20),
        ('atr_period', 14),
        ('return_period', 20),
        ('return_threshold', 0.15),
        ('rsi_low', 40),
        ('rsi_high', 60),
        ('volume_mult', 1.2),
        ('hh_period', 20),
        ('swing_low_period', 5),
        ('atr_mult', 0.5),
        ('min_rr', 2.0),
        ('risk_pct', 0.01),
    )

    def __init__(self):
        self.ema20 = bt.indicators.EMA(self.data.close, period=self.p.ema_fast_period)
        self.ema50 = bt.indicators.EMA(self.data.close, period=self.p.ema_slow_period)
        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)
        self.vol_sma = bt.indicators.SMA(self.data.volume, period=self.p.vol_sma_period)
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)
        self.hh20 = bt.indicators.Highest(self.data.high, period=self.p.hh_period)
        self.swing_low5 = bt.indicators.Lowest(self.data.low, period=self.p.swing_low_period)

        self.order = None
        self.stop_order = None
        self.limit_order = None
        self.stop_price = None
        self.target_price = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order == self.order:
            if order.status == order.Completed:
                size = order.executed.size
                self.stop_order = self.sell(
                    exectype=bt.Order.Stop, price=self.stop_price, size=size
                )
                self.limit_order = self.sell(
                    exectype=bt.Order.Limit, price=self.target_price, size=size,
                    oco=self.stop_order
                )
            self.order = None
        elif order == self.stop_order:
            if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
                self.stop_order = None
        elif order == self.limit_order:
            if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
                self.limit_order = None

    def next(self):
        if self.position:
            if self.data.close[0] < self.ema20[0]:
                if self.stop_order is not None:
                    self.cancel(self.stop_order)
                if self.limit_order is not None:
                    self.cancel(self.limit_order)
                self.close()
            return

        if self.order is not None:
            return

        if len(self.data) <= self.p.return_period:
            return

        prior_close = self.data.close[-self.p.return_period]
        ret = (self.data.close[0] - prior_close) / prior_close
        if ret < self.p.return_threshold:
            return

        if not (self.ema50[0] > self.ema50[-1]):
            return

        if not (self.data.close[0] > self.ema20[0] and self.ema20[0] > self.ema20[-1]):
            return

        if self.data.low[0] <= self.ema20[0]:
            test_low = self.data.low[0]
        elif self.data.low[-1] <= self.ema20[-1]:
            test_low = self.data.low[-1]
        else:
            return

        if not (self.data.close[0] > self.ema20[0] and self.data.close[0] > self.data.high[-1]):
            return

        if not (self.p.rsi_low <= self.rsi[0] <= self.p.rsi_high):
            return

        if not (self.data.volume[0] > self.p.volume_mult * self.vol_sma[0]):
            return

        entry_price = self.data.close[0]
        target_price = self.hh20[0]
        stop_price = min(self.swing_low5[0], test_low) - self.p.atr_mult * self.atr[0]

        risk = entry_price - stop_price
        reward = target_price - entry_price
        if risk <= 0:
            return
        if reward < self.p.min_rr * risk:
            return

        risk_amount = self.broker.getvalue() * self.p.risk_pct
        size = int(risk_amount / risk)
        if size <= 0:
            return

        self.stop_price = stop_price
        self.target_price = target_price
        self.order = self.buy(size=size)
